package com.vandorlabs.neoforge.programmer;
import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.item.component.CustomData;
/** Actual failed partial reread preserves prior physical ownership and every rejected input. */
final class ProgrammerRereadChecks {
 private static int checks;
 private static void need(boolean value,String reason){checks++;if(!value)throw new AssertionError("Programmer reread: "+reason);}
 private static CompoundTag incoming(boolean malformed){var tag=new CompoundTag();if(malformed)tag.putShort(NativeProgrammerSnapshot.VERSION,(short)1);else tag.putInt(NativeProgrammerSnapshot.VERSION,1);var caps=new CompoundTag();caps.putByteArray("future:partial",malformed?new byte[]{11,23,43}:new byte[]{7,19,41});tag.put("ForgeCaps",caps);return tag;}
 private static int occurrences(Tag value,CompoundTag target){int count=value.equals(target)?1:0;if(value instanceof CompoundTag compound)for(String key:compound.getAllKeys())count+=occurrences(compound.get(key),target);else if(value instanceof ListTag list)for(Tag entry:list)count+=occurrences(entry,target);return count;}
 private static CompoundTag verify(NativeProgrammerEntity owner,ServerLevel level){var saved=owner.saveWithoutMetadata(level.registryAccess());var outer=saved.getCompound(NativeProgrammerEntity.QUARANTINE);var earlier=outer.getCompound("Previous").getCompound(NativeProgrammerEntity.QUARANTINE);var prior=earlier.getCompound("Previous");need(owner.inert()&&owner.isEmpty(),"no usable physical service after quarantine");need(outer.getCompound("Incoming").equals(incoming(true))&&earlier.getCompound("Incoming").equals(incoming(false)),"both untouched rejected envelopes retained");var decoded=NativeProgrammerSnapshot.prepare(prior,level.registryAccess());need(decoded.item(0).getCount()==1&&NativeCredentialItems.company(decoded.item(0))==2&&decoded.item(1).getCount()==1&&NativeCredentialItems.company(decoded.item(1))==3,"both prior physical credentials retained");need(decoded.item(1).getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getString("RereadOwner").equals("prior physical chip"),"complete prior item data retained");need(occurrences(saved,prior)==1&&occurrences(saved,incoming(false))==1&&occurrences(saved,incoming(true))==1,"each quarantined snapshot occurs exactly once");need(!owner.getUpdateTag(level.registryAccess()).toString().contains("RereadOwner"),"safe DTO excludes quarantined physical contents");try{NativeProgrammerSnapshot.prepare(saved,level.registryAccess());throw new AssertionError("quarantine became usable");}catch(IllegalArgumentException expected){}return saved;}
 static void write(ServerLevel level,NativeProgrammerBlock block,BlockPos pos){for(int part=0;part<4;part++){var cell=NativeProgrammerBlock.cell(pos,Direction.NORTH,part);level.getChunkAt(cell);level.setBlock(cell,block.defaultBlockState().setValue(NativeProgrammerBlock.PART,part),3);}var owner=(NativeProgrammerEntity)level.getBlockEntity(pos);owner.setItem(0,NativeCredentialItems.accessCard(2));var chip=NativeCredentialItems.dataChip(3);var marker=new CompoundTag();marker.putString("RereadOwner","prior physical chip");chip.set(DataComponents.CUSTOM_DATA,CustomData.of(marker));owner.setItem(1,chip);var prior=owner.saveWithoutMetadata(level.registryAccess());var first=incoming(false);owner.loadWithComponents(first,level.registryAccess());var saved=owner.saveWithoutMetadata(level.registryAccess());need(owner.inert()&&saved.getCompound(NativeProgrammerEntity.QUARANTINE).getCompound("Previous").equals(prior)&&saved.getCompound(NativeProgrammerEntity.QUARANTINE).getCompound("Incoming").equals(first),"failed partial reread keeps prior owner and untouched incoming");owner.loadWithComponents(first,level.registryAccess());need(owner.saveWithoutMetadata(level.registryAccess()).equals(saved),"identical partial reread is idempotent");owner.loadWithComponents(incoming(true),level.registryAccess());saved=verify(owner,level);owner.loadWithComponents(first,level.registryAccess());owner.loadWithComponents(incoming(true),level.registryAccess());need(owner.saveWithoutMetadata(level.registryAccess()).equals(saved),"older and latest repeated failures cannot duplicate or replace quarantine");System.out.println("[vandorlabs][programmer-reread] write PASS checks="+checks);}
 static CompoundTag read(ServerLevel level,BlockPos pos){var owner=(NativeProgrammerEntity)level.getBlockEntity(pos);var saved=verify(owner,level);owner.loadWithComponents(incoming(false),level.registryAccess());owner.loadWithComponents(incoming(true),level.registryAccess());need(owner.saveWithoutMetadata(level.registryAccess()).equals(saved),"restart then repeated partial failure preserves sole capsule");System.out.println("[vandorlabs][programmer-reread] read PASS checks="+checks);return saved;}
}
